        /// <summary>
        /// Паспортные константы термодатчика
        /// </summary>
        protected XmlTdConst ConstTd;

        /// <summary>
        /// Тип термодатчика
        /// </summary>
        protected TypeTd TdType
        {
            get
            {
                var tdType = TypeTd.TEMPER;
                if (!Enum.TryParse(ConstTd.TdType, out tdType))
                    return TypeTd.TEMPER;
                return tdType;
            }
        }

        protected double[][] _tableTd;
        /// <summary>
        /// Таблица пересчета вольов в температуру для термодатчика выбранного в ПК
        /// </summary>
        protected double[][] TableTd
        {
            get
            {
                if (_tableTd != null)
                    return _tableTd;

                double[,] tab;
                switch (TdType)
                {
                    default:
                        tab = new double[,] { { -5000.0, -5000.0 }, { 5000.0, 5000.0 } };
                        break;
                    case TypeTd.ТПП_R:
                        tab = TableTppR;
                        break;
                    case TypeTd.ТПП_S:
                        tab = TableTppS;
                        break;
                    case TypeTd.ТПП_XA:
                        tab = TableTppXA;
                        break;
                    case TypeTd.ТПР_B:
                        tab = TableTprB;
                        break;
                    case TypeTd.ТПР_Bx2:
                        tab = TableTprBx2;
                        break;
                }

                _tableTd = new double[tab.Length / 2][];
                for (int i = 0; i < tab.Length / 2; i++)
                    _tableTd[i] = new double[] { tab[i, 0], tab[i, 1] };
                return _tableTd;
            }
        }
        public ClassBaseTd(XmlTdConst constTd)
        {
            ConstTd = constTd;
            StatusTd = true;
        }

        /// <summary>
        /// Список значений температур для усреднения
        /// </summary>
        protected List<double> LstTd = new List<double>();

        public double EvalfT(double u)
        {
            if (TdType == TypeTd.TABLE)
            {
                var corrTempTable = ConstTd.MasAcpConst[0].GetValue(u);
                return Correction(corrTempTable);
            }


            if (u < TableTd.First()[1])
            {
                var corrTempTdD = TableTd.First()[0];
                return Correction(corrTempTdD);
            }

            if (u > TableTd.Last()[1])
            {
                var corrTempTdU = TableTd.Last()[0];
                return Correction(corrTempTdU);
            }

            var min = TableTd.Where(dat => dat[1] <= u).Last();
            var max = TableTd.Where(dat => dat[1] >= u).First();

            if (max[1] == min[1])
            {
                var corrTempMax = max[0];
                return Correction(corrTempMax);
            }

            var k = (max[0] - min[0]) / (max[1] - min[1]);
            var b = min[0] - k * min[1];

            var temp = k * u + b;
            return Correction(temp);
        }

        private double Correction(double inTemp)
        {
            var tab = ConstTd.CorrectionTable;
            if (tab == null)
                return inTemp;

            var points = tab.UsedPoints.OrderBy(dat => dat.X).Distinct().ToArray();

            if (points.Length == 0)
                return inTemp;

            if (inTemp < points[0].X)
                return inTemp;
            if (inTemp > points.Last().X)
                return inTemp;

            var minMas = points.Where(dat => dat.X <= inTemp).ToArray();
            var maxMas = points.Where(dat => dat.X > inTemp).ToArray();

            if (minMas.Length != 0 && maxMas.Length == 0)
                return minMas.Last().Y;
            if (minMas.Length == 0 && maxMas.Length != 0)
                return maxMas[0].Y;


            var beg = minMas.Last();
            var end = maxMas.First();

            var k = (beg.Y - end.Y) / (beg.X - end.X);
            var b = beg.Y - k * beg.X;

            var temp = k * inTemp + b;
            return temp;
        }

        //int maxErr = 10;
        //double maxDelta = 10;
        /// <summary>
        /// Статус термодатчика
        /// </summary>
        public bool StatusTd { get; set; }
        /// <summary>
        /// Количество повторных сбоев
        /// </summary>
        private int ErrCnt { get; set; }

        private bool AnalyseNewT(double t)
        {
            if (LstTd.Count < ConstTd.Aver)
                return true;

            if (Math.Abs(AverTd - t) <= ConstTd.ErrorDT)
            {
                ErrCnt = 0;
                return true;
            }

            if (Math.Abs(AverTd - t) > ConstTd.ErrorDT)
                ErrCnt++;

            if (ErrCnt >= ConstTd.MaxErrorCnt)
                StatusTd = false;

            return false;
        }
        /// <summary>
        /// Добавление нового значения термодатчика
        /// </summary>
        /// <param name="u">Напряжение на термодатчике</param>
        /// <returns></returns>
        public double Add(double u)
        {
            var t = EvalfT(u);
            if (!AnalyseNewT(t))
                return AverTd;

            LstTd.Add(t);
            if (LstTd.Count > ConstTd.Aver)
                LstTd.RemoveAt(0);

            return AverTd;
        }

        /// <summary>
        /// Усредненное значение термодатчика
        /// </summary>
        public virtual double AverTd
        {
            get
            {
                if (!StatusTd)
                    return 10000.0;

                if (LstTd.Count == 0)
                    return 0.0;
                return LstTd.Average();
            }
        }

    }
